// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, bytes calldata data, address target) public {
        address nonOwner = makeAddr("nonOwner");
        vm.assume(nonOwner != c.owner());
        vm.deal(nonOwner, amount);
        vm.deal(address(c), 0);
        bool ok;
        vm.prank(nonOwner);
        try c.sendMoney(target, amount, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
